    'catalog_invalid_icon' => 'Folosiți o pictogramă de cel mult 128 KiB și 512 × 512 pixeli.',
    'international_format_works_anywhere_e_g_45_1_e06a0cd1' => 'Formatul internațional funcționează oriunde, de exemplu +45 12 34 56 78.',
    'it_gets_a_client_secret_shown_once_on_the_ne_356c8ac4' => 'Primește un secret de client, afișat o singură dată pe ecranul următor.',
    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Este apelat din nou la punctul hook începând cu următoarea operație corespunzătoare.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Își pierde imediat posibilitatea de a acționa în numele dvs. și va trebui să vă ceară din nou aprobarea.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Nu mai este apelat la punctul hook. Operația la care răspundea continuă fără el.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Încetează imediat să funcționeze. Orice îl mai folosește nu se va putea conecta.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Folosește PKCE și nu primește un secret — nu există nimic de divulgat din browser sau telefon.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'De acum, evenimentele sale sunt acceptate fără verificare — sau refuzate, dacă modul strict este activat.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Membrii săi se pot conecta din nou, iar mediile sale reiau serviciile de autentificare.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Propriile date de autentificare, în locul celor ale mediului pentru acest furnizor.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Cheie creată. Lipiți-o în frontend — este destinată utilizării publice.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Cheie rotită — copiați acum cheia nouă. Cheia veche continuă să funcționeze timp de 24 de ore.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Afișați butoane Google, GitHub, Apple și ale altor furnizori pe pagina de autentificare, pentru persoanele care preferă un cont existent în locul unei parole noi. Configurați furnizorul o singură dată pentru mediu și va fi disponibil în toate organizațiile. O organizație poate folosi propriile date de acces sau poate dezactiva un furnizor. Introduceți datele de acces; restul se completează automat. Adresa transmisă de un furnizor nu este niciodată suficientă, singură, pentru a accesa un cont existent aici.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Cheile pe care codul dvs. le prezintă către Cbox ID, cu o filă pentru fiecare tip. O cheie secretă, numită și cheie de administrare, permite backendului să gestioneze organizațiile, membrii, invitațiile, rolurile și aplicațiile unui mediu. O cheie a spațiului de lucru apelează API-ul acestuia cu un rol predefinit. O cheie publicabilă este folosită într-o aplicație de browser și funcționează doar din originile permise. Cheile secrete și cele ale spațiului de lucru sunt afișate o singură dată: copiați-le la creare și revocați-le imediat dacă sunt divulgate.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Înregistrați aplicații care acceptă acest mediu ca furnizor de identitate SAML, astfel încât utilizatorii se autentifică folosind conturile pe care le au deja aici. Asociați fiecare aplicație cu organizația sa pentru a permite accesul doar membrilor organizației respective. Fără o organizație asociată, aplicația este disponibilă tuturor utilizatorilor mediului. Aceasta este direcția de ieșire. Pentru autentificarea cu un cont de companie din alt sistem, folosiți SSO pentru companii din secțiunea Autentificare.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Alegeți frameworkul folosit. Va fi creată o aplicație cu redirecționare către serverul local de dezvoltare, blocul de configurare a mediului de copiat și codul pentru autentificarea utilizatorului. Pagina așteaptă o autentificare reală. Mai jos sunt pașii pentru pregătirea produsului: identitate vizuală, organizații, autentificare unică, un agent, un coleg și producție. Fiecare pas este bifat pe baza datelor existente în mediu, niciodată manual.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar evaluează fiecare autentificare și înregistrare: încercări cu date de acces furate, viteză tipică boților, deplasări imposibile, dispozitive noi, rețele de anonimizare și adrese temporare, plus regulile și listele dvs. de permisiuni și blocări. Înregistrați fiecare decizie și, după activarea aplicării regulilor, blochează accesul sau solicită un al doilea factor. Consultați deciziile aici înainte de activare și când cineva nu se poate autentifica.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Comutatoare de funcționalități pe care aplicațiile le consultă pentru o persoană dintr-o organizație. Activați o funcționalitate pentru utilizatori sau organizații specifice ori pentru o parte din toți utilizatorii. Fiecare aplicație citește același răspuns, din token sau prin API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software care acționează în acest mediu cu o cheie de administrare: Claude Code, Cursor, un bot intern sau propriul backend. Fiecare are doar domeniile de acces pe care i le-ați acordat și așteaptă aprobarea dumneavoastră acolo unde ați solicitat-o.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Sistemul receptor păstrează același secret. Un secret hexazecimal de 64 de caractere devine whsec_ urmat de codificarea base64 a acelui șir hexazecimal — "whsec_" + base64(secret). Un secret care începe deja cu whsec_ este folosit ca atare.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizații, utilizatori și sesiuni active din toate mediile acestei instalări, precum și organizațiile cu cei mai mulți membri. Această vizualizare doar citește datele și nu schimbă niciodată mediul selectat în consolă.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Toate persoanele care se pot autentifica în această organizație și invitațiile trimise care nu au fost încă acceptate. Invitați persoane prin e-mail; acestea își configurează singure autentificarea, astfel încât nu gestionați niciodată parola altcuiva.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Permiteți autentificarea cu un cont existent. Configurați un furnizor o singură dată pentru mediu și acesta devine disponibil în toate organizațiile. O organizație poate folosi propriile acreditări sau poate dezactiva un furnizor.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar evaluează fiecare autentificare și înregistrare: încercări cu acreditări furate, viteză specifică boților, deplasări imposibile, dispozitive noi, rețele de anonimizare, adrese temporare și propriile reguli și liste. Înregistrați și motivul deciziei.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Acest utilizator nu se mai poate autentifica în nicio aplicație din acest mediu, iar sesiunile existente nu vor mai funcționa de la următoarea cerere. Înregistrările sale sunt păstrate și îl puteți reactiva oricând.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Evaluarea se face în această ordine: lista de blocare, lista de permisiuni, regulile proprii de sus în jos (decide prima care se potrivește), apoi regulile încorporate (decide cea mai strictă dintre cele declanșate). Dacă nu există nicio potrivire, accesul este permis.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Majoritatea integrărilor ar trebui să folosească webhookuri: acestea rulează după eveniment și nu pot bloca operațiunea. Folosiți un hook doar când sistemul dumneavoastră trebuie să intervină în timpul autentificării sau emiterii unui token.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Cheile create apar aici, împreună cu data ultimei utilizări a fiecăreia.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Lăsați gol pentru a nu bloca — în această implementare, blocarea implicită este dezactivată.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Permiteți persoanelor să se conecteze cu contul de companie pe care îl au deja, în locul unei parole separate aici.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Flux de jurnal salvat. Livrarea va fi reîncercată la următoarea rulare.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Cheie de administrare creată — copiați-o acum, nu va mai fi afișată.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Asociați un grup cu rolurile pe care trebuie să le aibă toți membrii săi. Apartenența se sincronizează, iar rolurile o urmează.',
