    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 aparțin unui API pe care această aplicație nu îl poate utiliza. Sunt excluse din toate tokenurile; eliminați-le din domeniile de acces introduse manual.',
