    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 nu are încă permisiuni, deci :part2 :part3 este gol. Numele rolului rămâne disponibil pentru aplicație. :part4',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Echipa se administrează din Spațiu de lucru › Echipă, de către cineva cu un rol în spațiul de lucru, nu de aici.',
    '_part1_only_d798c565' => 'doar :part1',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Nimic de aici nu este încă stabilit de :part3. Dacă modificați ceva mai jos, devine o regulă proprie a acestei organizații.',
    '_part1_part2_only_5ce234b9' => 'doar :part1 :part2',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Câmpul :part2 reprezintă altceva: ce avea voie să solicite :part3 :part4, nu ce poate face această :part5.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Bifați domeniul de acces :part2 :part3 când înregistrați aplicația. Tokenul de identitate va conține aceleași nume de roluri în câmpul :part4, numele căutat de Kubernetes, Grafana și Vault. Nu mai trebuie creat nimic.',
