    '_together_with_the_issuer_part1_because_the_app_also_si_e67abff1' => ', împreună cu emitentul :part1, deoarece aplicația autentifică și utilizatori',
    'a_conflict_is_written_over_roles_so_there_is_nothing_to_1ee9ecc5' => 'Un conflict se definește între roluri, deci nu există încă roluri între care să îl definiți. Creați mai întâi rolurile.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'O pagină pe :part1. Lăsați necompletat pentru a deschide consola, cu :part2 indicat în invitație.',
    'a_part1_key_you_can_compose_into_roles_e_g_part2_part3_2714a35b' => 'O cheie :part1 pe care o puteți include în roluri, de exemplu :part2. :part3 :part4',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'O permisiune stabilește ce poate face o :part1 după autentificare. Ce poate solicita o :part2 este un domeniu de acces, stabilit când o înregistrați în :part3 :part4.',
    'a_user_rule_beats_an_organization_rule_which_beats_the_74a29528' => 'O regulă pentru un utilizator are prioritate față de regula organizației, care are prioritate față de lansarea graduală, care are prioritate față de valoarea implicită. Dacă indicatorul este dezactivat, este dezactivat pentru toți.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Accesul se acumulează: persoanele schimbă echipele, dar păstrează permisiunile vechi, fără ca cineva să observe până când întreabă un auditor. O revizuire înregistrează starea curentă a accesului și cere confirmarea necesității fiecărei acordări.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Tokenurile de acces ale acestei aplicații indică :part1 ca destinatar :part2. API-ul trebuie să accepte un token numai dacă îl indică drept destinatar.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Tokenurile de acces ale acestei aplicații indică emitentul mediului, :part1 :part2, ca destinatar. Acest lucru se schimbă când aplicația deține un domeniu de acces al unuia dintre API-urile înregistrate.',
    'acme_dashboard_0b433bd7' => 'Panou Acme',
    'add_permissions_manually_3596f1b0' => 'adăugați permisiuni manual',
    'already_sent_try_again_in_seconds_seconds_and_check_the_e294712c' => 'A fost deja trimis. Timp până la o nouă încercare (s): :seconds. Între timp, verificați dosarul de spam al destinatarului.',
    'an_app_registered_here_can_sign_your_people_in_and_read_f35bdb6c' => 'O aplicație înregistrată aici poate autentifica utilizatorii și le poate citi rolurile, astfel încât să administrați accesul într-un singur loc, nu separat în fiecare produs.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'O aplicație își înregistrează catalogul prin SDK. :part1 :part2 Puteți crea rolul acum și îi puteți adăuga permisiuni când definițiile acestora devin disponibile.',
    'an_owner_or_admin_can_add_sms_only_next_to_a_stronger_f_07347449' => 'Un proprietar sau administrator poate adăuga SMS doar alături de un factor mai puternic. Dacă are numai SMS, i se va cere să adauge alt factor.',
    'and_part1_more_1468d675' => 'și încă :part1',
    'anyone_can_create_an_account_in_part1_and_becomes_the_o_ff47cb27' => 'Oricine poate crea un cont în :part1 și devine proprietarul propriei organizații.',
    'apps_registered_by_the_organizations_in_this_environmen_1fd60d9d' => 'Aplicațiile înregistrate de organizațiile din acest mediu pot primi acest domeniu de acces. Lăsați opțiunea dezactivată dacă domeniul trebuie să fie disponibil numai propriilor aplicații.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Aplicațiile trimit utilizatorii la înregistrare cu :part1 și cer unei persoane autentificate să creeze o organizație cu :part2. Ambele opțiuni sunt disponibile numai cât timp această setare este activă.',
    'apps_that_hold_it_keep_it_as_a_typed_scope_which_no_lon_6498e819' => 'Aplicațiile care îl dețin îl păstrează ca domeniu de acces introdus manual, care nu mai oferă acces la acest API. Tokenurile nu îl mai includ pentru acest destinatar.',
    'ask_a_sign_up_radar_flags_to_prove_it_is_a_person_cloud_5b5f2963' => 'Cereți unei persoane a cărei înregistrare este semnalată de Radar să dovedească faptul că este om prin Cloudflare Turnstile. Dacă opțiunea este dezactivată, înregistrarea semnalată cere în schimb confirmarea adresei de e-mail.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Verificarea se face exact ca în aplicație (:part1), ținând cont de toate regulile de moștenire definite în schemă.',
    'at_least_as_fresh_as_bb83225d' => 'Cel puțin la fel de recent ca',
