    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Confirmați ce este încă necesar și revocați ce nu mai este. Nimic nu intră în vigoare până la închiderea revizuirii; atunci un rol de administrare și asistență revocat este retras simultan din toate organizațiile.',
