  "roles": [":part1"],
  "permissions": [:part2]
}',
    'api_read_reports_export_db00448d' => 'api.read, reports.export',
    'billing_read_reports_write_36538bcc' => 'billing:read, reports:write',
    'document_readme_29e90756' => 'document:readme',
    'document_readme_viewer_user_alice_f9405db5' => 'document:readme#viewer@user:alice',
    'https_app_example_com_https_staging_example__ad77bfc7' => 'https://app.example.com
https://staging.example.com',
    'invoices_create_be35ad14' => 'invoices:create',
    'invoices_read_459482fd' => 'invoices:read',
    'user_alice_dabd1db8' => 'user:alice',
    'valid_f5162206' => 'Valid',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Rolurile și permisiunile dintr-un token reprezintă starea de la un moment dat. Înainte de fiecare acțiune protejată, obțineți o decizie de acces actuală de la Cbox ID și verificați în aplicație accesul la resursa concretă. Conținutul tokenului, singur, nu reflectă revocările ulterioare:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Metodele dumneavoastră de autentificare și sesiunile active. O cheie de acces este opțiunea cea mai sigură și mai rapidă: dispozitivul o deblochează prin amprentă sau recunoaștere facială, fără o parolă care să poată fi furată prin phishing.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Fiecare acțiune este acceptată așa cum o trimite aplicația. Adăugați o schemă pentru o acțiune ca evenimentele sale să fie validate la primire. Coerența jurnalului se asigură când este scris un eveniment, nu când îl citește cineva.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Fiecare cheie API din configurația sau fișierul de mediu al unei aplicații este o cheie pe care nu o puteți roti centralizat sau revoca rapid. Stocată aici, este criptată, accesul este acordat per aplicație și poate fi revocată cu un clic.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Butonul nu mai apare, iar acreditările sunt șterse. Persoanele care s-au autentificat prin acest furnizor își păstrează conturile și pot folosi în continuare parola. Pentru a păstra acreditările, dezactivați furnizorul în loc să îl ștergeți.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Sensul invers: Cbox ID trimite persoanele din organizație către celelalte produse SaaS folosite de companie, prin endpointurile SCIM ale acestora. Un singur loc pentru acordarea și retragerea accesului, în loc de un panou de administrare pentru fiecare furnizor.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Creați organizația, proprietarul ei, primul produs și mediul de producție al acelui produs. Proprietarul primește prin e-mail un link pentru a-și seta propria parolă; nu o alegeți în locul său.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'În prezent, cineva adaugă și elimină manual persoane aici. Conectați directorul pe care compania îl întreține deja, iar ambele operațiuni devin automate, inclusiv eliminările, care sunt cel mai ușor de uitat.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Toate tokenurile emise de acesta sunt revocate acum și nu mai poate fi folosit pentru autentificări noi. O aplicație care verifică singură tokenurile nu le mai acceptă când expiră, cel târziu la încheierea sesiunii.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'În timpul migrării de la alt sistem, aplicația poate declara unde se află vechiul mecanism de autentificare, în manifestul său, lângă roluri. Declarația apare aici pentru aprobare înainte de a produce vreun efect.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Creați o regulă pentru a permite, a solicita verificare suplimentară sau a bloca pe baza a ceea ce știți despre utilizatori. Solicitați verificare suplimentară pentru autentificările din afara țărilor în care operați sau exceptați rețeaua biroului de la regulile de frecvență.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Verificarea unui domeniu deținut, precum acme.com, permite Cbox ID să recunoască persoanele după adresa de e-mail și să le trimită direct la furnizorul dumneavoastră, fără să aleagă butonul de autentificare potrivit.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Un furnizor de identitate care importă metadatele furnizorului de servicii folosește acest URL în loc să primească separat ID-ul entității și URL-ul ACS. Funcționează înainte de completarea părții de configurare a furnizorului de identitate.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Această acțiune nu poate fi anulată. Acreditările, apartenențele și datele personale sunt șterse, iar contul este pseudonimizat. Dacă persoana este singurul proprietar al unei organizații, transferați mai întâi proprietatea.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Acționați ca această persoană, în sesiunea sa și cu drepturile sale de acces. Accesul este limitat la 30 de minute și doar la citire acolo unde consola poate impune această restricție. Fiecare cerere este înregistrată pe numele dumneavoastră.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Suspendarea este singura modificare făcută pe această pagină și este reversibilă. Selectarea și deschiderea unui mediu schimbă doar vizualizarea consolei; nu modifică nimic în niciunul dintre medii.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'În prezent, persoanele se autentifică folosind acreditări păstrate aici. Conectați furnizorul dumneavoastră ca acestea să folosească deja existentul cont al companiei și să piardă accesul aici imediat ce îl dezactivați la furnizor.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Nu se emite un secret nou. De la următoarea încercare, inclusiv reîncercările, livrările conțin antetele celeilalte scheme. Un receptor care nu a fost actualizat le va respinge pe toate.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Trimiteți acest link de unică folosință persoanei care administrează furnizorul lor de identitate, dacă nu l-a primit prin e-mail. Funcționează fără cont până la expirare. Copiați-l acum: este afișat o singură dată.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Software-ul din acest mediu care așteaptă autorizarea unei persoane. Un agent a cărui cheie necesită aprobare se oprește și întreabă persoana care a creat cheia. Răspundeți aici sau pe telefon.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'O organizație reunește utilizatori, metode de autentificare și roluri. Creați una mai sus sau inițializați mediul cu prima organizație și primul administrator din ecranul Medii.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Adăugați persoana într-una dintre organizațiile de mai jos pentru a-i acorda acces în interiorul ei. Dacă aplicațiile nu au propria separare între organizații, acordați-i un rol de administrare și asistență, valabil în întregul mediu.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Un rol de administrare și asistență este acordat propriului personal în întregul mediu. Se aplică în fiecare organizație, iar administratorii organizațiilor nu îl pot vedea sau modifica.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Cererile apar automat aici când o aplicație sau un agent are nevoie de aprobarea dumneavoastră pentru a acționa în numele dumneavoastră. Nu aveți nimic de făcut până atunci. Dacă apare o cerere pe care nu ați inițiat-o, refuzați-o.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS-ul este cel mai slab al doilea factor: cine preia controlul numărului de telefon primește codurile. Preferați o aplicație de autentificare sau o cheie de acces și folosiți SMS doar dacă nu puteți utiliza aceste opțiuni.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Identitatea vizuală implicită a mediului: aspectul paginii de autentificare găzduite, sigla, faviconul, precum și numele și expeditorul afișate utilizatorilor. Fiecare organizație le moștenește dacă nu își definește propriile setări.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Detaliile organizației din mediul țintă: membri, SSO, domenii, drepturi de acces și activitate recentă. Singura modificare posibilă pe această pagină este starea organizației.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Toate spațiile de lucru din această instalare. Deschideți unul pentru a-i explora produsele și mediile. Suspendarea deconectează membrii și oprește autentificarea în toate mediile deținute de acel spațiu.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Aplicația trimite aceste evenimente printr-un apel per lot, fiecare eveniment indicând organizația în care s-a produs. Apar aici și pentru administratorii acelei organizații pe măsură ce sunt primite.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Este disponibil pe toate paginile de autentificare ale mediului. Alegeți o organizație pentru a-i configura propriul furnizor, care îl înlocuiește pe cel al mediului pe pagina organizației respective.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code deschide browserul pentru autentificare aici și vă întreabă ce doriți să permiteți. Nu aveți o cheie de păstrat în siguranță. Orice client MCP care se autentifică prin OAuth funcționează la fel cu acest URL.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Un spațiu de lucru din această instalare: echipa, proiectele și toate mediile deținute de acele proiecte. Suspendarea deconectează membrii și oprește autentificarea în toate aceste medii.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'La nivelul întregului mediu: orice persoană cu un cont în acest mediu, din orice organizație, se poate autentifica în această aplicație. Indicați o organizație dacă nu intenționați acest acces extins.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Autentificarea cu Entra ID, Okta sau Google Workspace este disponibilă în planul Enterprise. Contactați echipa care gestionează contul dumneavoastră pentru a o activa pentru această organizație.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Unde sunteți autentificat, ce poate acționa în numele dumneavoastră și ce s-a întâmplat cu contul. Dacă vedeți ceva ce nu recunoașteți, închideți sesiunea respectivă și schimbați parola.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Câte persoane s-au autentificat și cât de des au apelat aplicațiile API-ul în ultimele 30 de zile. Aceste date vă ajută să observați încărcarea și anomaliile; nu reprezintă o factură.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Acest utilizator deține sau administrează o organizație, iar identitatea sa nu poate fi preluată. Intrarea într-un astfel de cont ar putea oferi persoanei care o face control de durată asupra organizației.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Chei API prezentate altor servicii de aplicațiile și agenții dumneavoastră. Fiecare valoare este criptată la stocare, transmisă doar aplicațiilor autorizate și nu mai este afișată după salvare.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplicații care cer să acționeze în numele unuia dintre utilizatori. Fiecare utilizator își aprobă propriile cereri. Refuzați una aici doar dacă pare abuzivă; refuzul este înregistrat în jurnalul de audit.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Frecvența importului și câmpurile proprii ale sistemului HR de copiat pentru fiecare persoană, precum centrul de cost sau locația. Modificarea câmpurilor face ca următoarea rulare să fie completă.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Linkuri oferite administratorului IT al acestei organizații care încă permit accesul. Revocarea unui link îl invalidează imediat; configurația deja realizată prin el rămâne.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Cererile agenților de a acționa în numele unui utilizator apar aici pe măsură ce sosesc. Fiecare utilizator își aprobă propriile cereri. Această pagină servește la refuzarea celor care par abuzive.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Când sunt îndeplinite TOATE condițiile, Radar execută acțiunea acestei reguli și nu mai verifică regulile următoare. Regulile sunt evaluate după listele de permisiuni și blocare și înaintea regulilor încorporate.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Evenimentele de audit trimise de aplicație despre toate organizațiile deservite, începând cu cele mai recente. Evenimentele fiecărei organizații formează propriul lanț de hashuri.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Tot ce a configurat organizația și ce mai rămâne de făcut. Lista de configurare urmărește starea reală: un pas este bifat automat în momentul în care este efectiv finalizat.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Ca administrator, adăugați și o aplicație de autentificare sau o cheie de acces. Preluarea numărului de telefon permite interceptarea SMS-urilor, așa că acestea nu pot fi singurul al doilea factor.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Ștergerea acestui spațiu de lucru elimină toate proiectele și mediile sale. Pentru a proteja furnizorii de identitate activi, această operațiune nu se face direct din interfață. Contactați asistența pentru a continua.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Persoana pierde imediat accesul la toate paginile platformei din această instalare, iar sesiunile existente nu vor mai funcționa de la următoarea cerere. O puteți reactiva aici.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Domeniile verificate direcționează persoanele către propriul furnizor de identitate, o funcție a planului Enterprise. Contactați echipa care gestionează contul pentru a o activa pentru această organizație.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'O permisiune reprezintă o acțiune pe care un rol o poate efectua, de exemplu crearea facturilor sau citirea rapoartelor. Puteți defini aici permisiuni proprii, fără cod, apoi le puteți combina în roluri. Aplicațiile își pot înregistra automat permisiunile, astfel încât lista să corespundă regulilor pe care le aplică efectiv. Permisiunile create vă aparțin. Le puteți folosi pe cele partajate de mediu, dar nu le puteți modifica.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Regulile pentru parole, blocare, obligativitatea autentificării cu doi factori și a autentificării unice, aplicate la fiecare autentificare. Pentru întregul mediu se stabilește și disponibilitatea cheilor de acces și a linkurilor de autentificare, precum și durata sesiunii. Mediul definește regulile de bază moștenite de toate organizațiile. O organizație poate înăspri regulile pentru parole și al doilea factor, dar nu le poate relaxa.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Acțiunile pentru care agenții din acest mediu așteaptă aprobarea unei persoane. Un agent a cărui cheie necesită aprobare pentru o acțiune se oprește și solicită acordul persoanei care a creat cheia. Aceasta poate răspunde de pe telefon sau aici. Orice administrator al mediului poate respinge o cerere suspectă. Mai jos sunt cererile aplicațiilor de a acționa în numele utilizatorilor, pe care fiecare utilizator le aprobă personal.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Sesiunile și tokenurile persoanei sunt revocate. Cheile de acces, factorii secundari, apartenențele, atribuirile de roluri, tokenurile API, secretele din seif, dispozitivele și toate copiile stocate ale datelor sale sunt șterse. Din cont rămâne doar o înregistrare pseudonimizată și dezactivată. Aplicațiile care sincronizează persoane de aici sunt notificate să șteargă persoana. Jurnalul de audit păstrează identificatorul opac, nu numele sau adresa.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Tot ce ați autorizat, inclusiv dispozitivele sau instrumentele de linie de comandă de pe care v-ați autentificat.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Datele pe care sistemele dvs. trebuie să le păstreze pentru această organizație. Rândurile fără cheie sunt eliminate.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Evaluate după regulile dvs. Fiecare regulă declanșată este înregistrată; cea mai strictă decide.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Livrarea se reia. Înregistrările create cât timp era oprită rămân în așteptare și vor fi trimise în următorul lot.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Livrarea se oprește imediat, iar datele de autentificare stocate sunt distruse. Jurnalul de audit rămâne intact.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Toate conexiunile dintre Cbox ID și alte sisteme, într-un singur loc: autentificare unică, autentificare socială, sincronizarea directoarelor și sisteme HR, provizionare către sisteme externe, aplicații SAML, webhookuri, hookuri, fluxuri de jurnale și conducte de date. Catalogul permite pornirea configurării oricăreia: fiecare card deschide pagina de configurare a acelui tip. Lista conexiunilor arată toate conexiunile existente și starea lor, începând cu cele cu erori.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Toate metodele de autentificare disponibile aici — parolă, chei de acces, link de autentificare, cont social, SSO pentru companii și al doilea factor — cu starea activării și locul unde se modifică. Majoritatea sunt stabilite de mediu; conexiunile SSO aparțin fiecărei organizații. Dacă instalarea a dezactivat sau limitat o metodă, pagina indică acest lucru și setarea responsabilă.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Un agent este orice software care acționează în acest mediu cu o cheie de administrare: un asistent AI precum Claude Code sau Cursor, un bot intern ori propriul backend. Atribuiți fiecăruia o cheie proprie, doar cu domeniile de acces necesare. Stabiliți ce acțiuni așteaptă aprobarea și revocați cheia imediat ce agentul termină sau ceva pare în neregulă.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Un API este un serviciu al dvs. care primește tokenuri de acces, de exemplu https://api.example.com. Înregistrați-l cu domeniile de acces pe care le recunoaște, pentru a le putea acorda. Decideți ce domenii pot solicita aplicațiile înregistrate de organizațiile din acest mediu. Tokenul destinat API-ului conține adresa acestuia ca audiență, pe care serviciul dvs. o verifică.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Cum este transmis istoricul de audit din Cbox ID: un export programat trimite înregistrările noi către SIEM sau arhivă la fiecare cinci minute. O sarcină zilnică de retenție creează un punct de control fără să șteargă date. Folosiți pagina pentru a obține istoricul de audit al unei persoane la o cerere de acces conform RGPD sau, în consola mediului, pentru a verifica funcționarea exporturilor.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Creați unul în Platformă › Medii, iar numărătorile sale vor apărea aici.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Toate mediile acestei instalări și ponderea fiecăruia în ansamblu',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Toate cozile prin care această instalare procesează sarcini în fundal și timpul de așteptare al celei mai vechi sarcini din fiecare',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Toate contoarele de utilizare pentru acest interval și cheile originale ale metricilor corespunzătoare',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Găsiți o organizație sau un utilizator în toate mediile, nu doar în cel selectat în consolă.',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Un singur proces de lungă durată, php artisan queue:autoscale, pornește și oprește procesele care execută sarcinile din coadă.',
    'prefix_74feac5e' => 'Prefix',
    'account_menu_value0_6ab6a9a2' => 'Meniul contului — :value0',
    'acme_inc_ee60673d' => 'Acme Inc.',
    'disconnect_value0_1d09db11' => 'Deconectați :value0?',
    'remove_value0_b597e5fb' => 'Eliminați :value0',
    'remove_value0_b8b38a7a' => 'Eliminați :value0?',
    'rename_value0_b709cc6f' => 'Redenumiți :value0',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Nu este inclus în planul acestei organizații.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Niciun domeniu revendicat nu corespunde. Încercați o parte din domeniu, fără @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Nicio conexiune nu corespunde acestui nume. Încercați alt termen de căutare.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Niciun director nu corespunde acestui nume. Încercați alt termen de căutare.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Niciun URL de endpoint nu corespunde căutării. Încercați altă căutare.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Nicio înregistrare nu corespunde acestor filtre. Încercați un termen mai general sau eliminați un filtru.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Niciun flux de jurnale nu corespunde acestui nume. Încercați altă căutare.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Nicio conexiune de ieșire nu corespunde acestui nume. Încercați altă căutare.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Toate elementele mărcii văzute de utilizatori, pe o singură pagină: sigla, faviconul, culorile, fontul și colțurile paginii de autentificare găzduite, cu previzualizare în timp real, plus numele produsului, expeditorul e-mailurilor și mesajul de bun venit. Configurați-le o dată pentru întregul mediu și toate organizațiile le moștenesc sau personalizați o organizație din fila Identitate vizuală.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Fiecare proiect din spațiul de lucru are propriul plan și propriul număr permis de medii. Acestea apar aici lângă utilizarea lunii curente: organizații, conexiuni de autentificare unică facturate și autentificări. Prețul ține cont de utilizatorii activi lunar și de conexiunile pentru companii, precum SSO și SCIM. Mediile de testare nu au costuri pentru conexiuni.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Toate cheile API create de persoanele din această organizație pentru aplicațiile sale: titularul, aplicația, permisiunile și ultima utilizare. O cheie poate face doar ceea ce poate face titularul și nu mai funcționează după plecarea acestuia din organizație. Revocați cheile divulgate sau nefolosite. Fiecare persoană își creează propriile chei în Contul meu.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'În timpul migrării de la alt sistem, o aplicație poate cere verificarea e-mailului și parolei unei persoane care nu există încă în Cbox ID la vechiul punct final de autentificare. Testați-l înainte de aprobare. O persoană acceptată este creată aici și nu mai este trimisă în sistemul vechi. Cât timp acel punct final nu este disponibil, persoanele care nu au fost încă migrate nu se pot autentifica.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Evenimentele de audit trimise de aplicație pentru fiecare organizație deservită: cine a făcut ce în produs și când. Sunt păstrate separat pentru fiecare organizație într-un lanț de hashuri și afișate administratorilor acelei organizații. Folosiți această funcție când o organizație solicită jurnalul de audit al contului său. Definiți scheme pentru a menține consecvența evenimentelor.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Nicio autorizare temporară viitoare nu va putea deschide acest secret. Revocarea este imediată și definitivă.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Nu există agenți activi. Cheile revocate și expirate rămân în listă pentru evidență.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Fără permisiuni — doar identifică deținătorul',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Nimic nu se schimbă pentru nimeni până când activați această opțiune. Testați mai întâi o autentificare.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Se stochează doar un hash. Dacă pierdeți cheia, revocați-o și creați alta.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Numai aplicațiile listate aici pot obține acces temporar la acest secret. Toate celelalte cereri sunt refuzate.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Sesiunile dvs. de pe toate celelalte dispozitive nu vor mai funcționa la următoarea cerere. Pe acest dispozitiv rămâneți autentificat.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Această organizație nu are încă membri. Nimeni nu se poate autentifica în ea până când este invitat sau adăugat prin aprovizionare.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Aici nu se setează o parolă. Persoana primește prin e-mail un link de autentificare și alege cum să se autentifice.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Fiecare pas este evaluat pe baza stării actuale, astfel încât ghidul arată întotdeauna situația reală a acestei organizații.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Copiați cheia acum și transmiteți-o agentului. Se păstrează doar un hash, deci cheia este afișată o singură dată.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Domeniile de e-mail ale organizației, fiecare confirmat printr-o înregistrare DNS TXT. După verificarea unui domeniu, puteți impune direcționarea către SSO: toate persoanele cu o adresă din acel domeniu folosesc conexiunea SSO pentru companii în locul parolei. Verificați toate domeniile folosite de persoane înainte de a vă baza pe autentificarea unică.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Modelul de acces al aplicației: tipuri de resurse precum documente și dosare, relații precum proprietar, editor și cititor și modul de moștenire. De exemplu, persoanele care pot vedea un dosar pot citi toate documentele sale. Aplicația înregistrează relațiile dintre persoane și resurse și întreabă la fiecare cerere dacă utilizatorul poate edita documentul. Schema stabilește răspunsul.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Acest mediu oferă un server MCP, metoda standard prin care asistenții AI apelează instrumente, alături de API-ul REST. Introduceți adresa și o cheie de administrare în Claude Code, Cursor sau alt client MCP. Agentul poate face exact ceea ce permit domeniile de acces ale cheii, cu aceleași verificări și același jurnal de audit ca în consolă.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'O cheie permite scripturilor și integrărilor dvs. să apeleze API-ul unei aplicații în numele dvs., fără autentificare interactivă. Poate face doar ceea ce puteți face dvs. în aplicație: dacă accesul vă este restrâns, cheia pierde același acces. Cheia este afișată o singură dată. Copiați-o la creare și revocați-o imediat dacă este divulgată sau nu mai este folosită.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Aprovizionarea se oprește, iar mapările grupurilor sunt eliminate. Persoanele create rămân.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Aprovizionarea se oprește imediat și toate mapările grupurilor sunt eliminate. Acțiunea nu poate fi anulată.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Aprovizionarea către aplicația destinație se oprește imediat. Acțiunea nu poate fi anulată.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Aprovizionarea către aplicația destinație se oprește imediat. Persoanele deja create acolo rămân.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Numărul de telefon a fost eliminat. Ceilalți factori de autentificare și codurile de recuperare ale persoanei rămân neschimbate.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Persoanele deja conectate păstrează domeniile de acces pe care le-au autorizat până când se conectează din nou.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Originile au fost actualizate. Modificarea intră în vigoare la următoarea cerere.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Este posibil ca alte sisteme să îl folosească. Modificarea lui schimbă URL-urile pe care le dețin.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Persoanele care depind de acest furnizor pierd această modalitate de autentificare. Acțiunea nu poate fi anulată.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Proiect suspendat. Mediile sale rămân active, dar nu pot fi adăugate altele noi până la reactivarea proiectului.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definiția rolului a fost activată. Deținătorii existenți folosesc acum aceste permisiuni.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Regula a fost activată. De acum, acordările de acces care ar încălca-o sunt blocate.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Schema a fost salvată. De acum, evenimentele acestei acțiuni sunt validate conform ei.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Schema a fost salvată. De acum, rezultatul fiecărei verificări este stabilit pe baza ei.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Respingeți evenimentele a căror acțiune nu are o schemă. Activați opțiunea după ce fiecare acțiune trimisă de aplicație are una.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Obiectele sunt scrise în prefix/yyyy/mm/dd/hh/batch.ndjson.gz, câte un eveniment pe linie.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Numai pentru stocare compatibilă cu S3, precum MinIO sau Cloudflare R2. Dacă este gol, se folosește endpointul AWS al regiunii.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Înregistrați acest URI de redirecționare permis la furnizor, exact așa cum este afișat.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhookurile, notificările de deconectare către aplicațiile conectate, actualizările de roluri preluate din acestea și e-mailurile din coadă sunt procesate în fundal de procesele de coadă, fără ca persoana să aștepte. Dacă nu rulează niciun proces, nimic nu este trimis, deși restul consolei pare în regulă. Aici puteți vedea problema.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'O revizuire în care verificați cine deține fiecare rol și confirmați dacă mai are nevoie de el. Accesul se acumulează neobservat: oamenii schimbă echipele, dar păstrează permisiunile vechi. Revizuirea permite eliminarea lor. Revocările se aplică la închiderea revizuirii, iar întregul proces este înregistrat pentru auditor.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Dacă aplicația declară ulterior alt URL, aprobarea este retrasă și vi se cere din nou. Schimbarea destinației parolelor necesită o nouă aprobare. Autentificarea delegată este o soluție de tranziție: când rămân puține persoane în sistemul vechi, dezactivați-o și trimiteți grupului respectiv mesaje de resetare a parolei.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Permiteți persoanelor să se autentifice cu un cont de companie existent, precum Microsoft Entra ID, Okta sau Google Workspace, în locul unei parole separate aici. Conectați furnizorul de identitate o singură dată și confirmați domeniile de e-mail. Toate persoanele din acele domenii sunt apoi direcționate către furnizor pentru autentificare.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Toate persoanele cu o identitate în acest mediu, indiferent de organizațiile din care fac parte. Deschideți o persoană pentru a reseta parola sau al doilea factor, a închide sesiunile, a dezactiva contul, a modifica organizațiile și rolurile atribuite ori a șterge definitiv datele la o cerere de exercitare a dreptului la ștergere.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Lipiți metadatele XML ale furnizorului sau URL-ul lor, iar câmpurile de mai jos se completează automat.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Lipiți această valoare la furnizorul de identitate, împreună cu tokenul bearer al directorului pe care îl conectați.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Configurați clientul OIDC cu aceste adrese. Mecanismul de descoperire expune automat toate endpointurile.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Înregistrați o aplicație care folosește acest mediu ca furnizor de identitate SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Înregistrați una pentru a permite unei aplicații să autentifice utilizatorii cu conturile pe care le au deja în acest mediu.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Numai aplicațiile listate aici primesc un token. Toate celelalte cereri sunt refuzate.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Nu sunt setate drepturi de utilizare pentru această organizație. Se folosesc valorile implicite ale instalării.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Organizațiile din mediul vizat, afișate ca arbore de administrare.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Aparține acestui mediu, nu unei organizații',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Operatorii platformei administrează mediile din întreaga instalare.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Utilizarea la nivelul întregii platforme, în toate mediile, nu doar în cel selectat în consolă.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Modul în care proprietarii și operatorii spațiilor de lucru se autentifică în Cbox ID se configurează în consola mediului platformei.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Aceste extensii rulează în timpul unei operațiuni, nu după ea, iar răspunsul lor schimbă rezultatul: endpointul poate adăuga informații într-un token sau poate refuza autentificarea. Intervin direct în executarea operațiunii; dacă endpointul este lent sau nu funcționează, persoana care încearcă să se autentifice va fi afectată.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Furnizorul de identitate creează, actualizează și dezactivează automat persoane aici prin standardul SCIM. Angajarea sau plecarea unei persoane înregistrată în sistemul HR ajunge în aplicații în câteva secunde, fără tichete și fără conturi rămase active — lucru esențial la plecarea cuiva.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Numărul de organizații, utilizatori, conexiuni de autentificare unică, aplicații și sincronizări de utilizatori din acest mediu, fiecare cu link către pagina proprie. Scurtăturile de mai jos pornesc cele mai frecvente acțiuni de creare: o organizație, un utilizator, o conexiune de autentificare unică sau o aplicație.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Un rol reprezintă o responsabilitate înțeleasă de aplicații, de exemplu „Editor” sau „Agent de asistență”. Aici decideți cine deține fiecare rol, iar fiecare aplicație stabilește ce permite rolul respectiv. Rolurile însoțesc persoana în toate aplicațiile conectate, astfel încât acordați și revocați accesul într-un singur loc.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Trimiteți o copie a fiecărei intrări din jurnalul de audit în instrumentele echipei de securitate, precum un SIEM, imediat ce este scrisă. Configurați o destinație pentru ca investigațiile să înceapă în instrumentele deja folosite, fără o cerere de export. Livrarea are loc cel puțin o dată, deci pot apărea duplicate.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Un spațiu de lucru apare aici de îndată ce cineva se înregistrează. Puteți folosi și Spațiu de lucru nou de mai sus pentru a crea unul.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Adăugați domeniul adreselor de e-mail ale persoanelor din această organizație, publicați înregistrarea TXT și verificați domeniul.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Confirmați că dețineți un domeniu de e-mail pentru a direcționa automat echipa către SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Confirmați că organizația deține un domeniu, apoi direcționați toți utilizatorii lui către autentificarea organizației.',
    'sandbox_environments_send_no_email_copy_the_setup_link_e5709a6a' => 'Mediile de testare nu trimit e-mailuri. Copiați linkul de configurare de mai jos și distribuiți-l personal.',
    'it_replaces_the_sealed_value_on_rotate_and_is_never_sho_cec701f1' => 'La rotație, înlocuiește valoarea criptată și nu mai este afișat. Păstrați o copie dacă aveți nevoie.',
    'replace_the_sealed_value_with_a_new_credential_the_stor_17b46d38' => 'Înlocuiți valoarea criptată cu date de autentificare noi. Valoarea stocată nu este niciodată afișată.',
    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'Este criptat în momentul salvării și nu mai este afișat. Păstrați o copie dacă aveți nevoie.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Este stocat criptat și nu mai este afișat. Lăsați gol pentru a păstra valoarea actuală.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Secretul a fost înlocuit, iar cel anterior nu mai funcționează. Copiați-l acum pe cel nou; nu va mai fi afișat.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Revocarea este imediată și definitivă. Nicio autorizare temporară viitoare nu va putea deschide acest secret.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Schemele de metadate sunt un subset al JSON Schema: un obiect ale cărui proprietăți sunt șiruri, numere, numere întregi, valori booleene sau null, cu enumerări și restricții de lungime, interval, tipar și format. Salvarea unei modificări creează o versiune nouă; evenimentele deja înregistrate păstrează versiunea folosită la validare.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Fiecare conexiune permite persoanelor să își conecteze propriul cont la un serviciu precum GitHub, Google sau Slack. Tokenurile sunt stocate criptat și reîmprospătate aici. Aplicațiile autorizate cer un token valid ori de câte ori apelează serviciul în numele persoanei, fără să stocheze ele însele tokenuri.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Un rol de administrare și asistență se acordă propriilor angajați, de exemplu echipelor de asistență sau operațiuni, la nivelul întregului mediu. Se aplică în fiecare organizație, iar administratorii organizațiilor nu îl pot vedea, acorda sau elimina. Un rol propriu al unei aplicații acordat astfel se aplică doar acelei aplicații.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Un mediu este un serviciu de identitate complet izolat, cu propriii utilizatori, propriile chei, autentificare și emitent. Aici sunt listate toate mediile acestei instalări, împreună cu spațiul de lucru de care aparțin. Creați un mediu, selectați-l în consolă și adăugați prima organizație și primul administrator.',
    'pick_the_app_and_tick_only_what_the_key_needs_you_can_c_69b0060d' => 'Alegeți aplicația și bifați numai ce îi trebuie cheii. Puteți crea oricâte chei doriți, câte una pentru fiecare integrare.',
    'scopes_saved_they_apply_from_the_next_token_this_app_as_db2304fa' => 'Domeniile de acces au fost salvate. Se aplică începând cu următorul token solicitat de această aplicație.',
    'self_service_sign_up_is_on_people_can_create_an_account_af9f74f0' => 'Înregistrarea pe cont propriu este activată. Persoanele pot crea un cont și propria organizație.',
    'start_from_a_preset_then_adjust_each_scope_is_marked_wi_60006824' => 'Porniți de la o presetare, apoi ajustați-o. Fiecare domeniu de acces indică cea mai dăunătoare acțiune pe care o permite.',
    'the_application_can_no_longer_sign_users_in_through_thi_72052d67' => 'Aplicația nu mai poate autentifica utilizatori prin acest mediu. Acțiunea nu poate fi anulată.',
    'add_one_below_to_offer_it_on_this_organization_s_page_51427e0a' => 'Adăugați unul mai jos pentru a-l oferi pe pagina acestei organizații.',
    'also_anything_that_deletes_or_revokes_ceebe14f' => 'Și orice acțiune care șterge sau revocă.',
    'api_do_this_page_s_actions_from_code_3cf98d0c' => 'API: executați acțiunile acestei pagini din cod',
