    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'Identificatorul prin care aplicația se identifică în cererile AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Un telefon cu aplicația de autentificare instalată permite răspunsul la cererile de aprobare și vă anunță când cineva se autentifică în contul dvs. Înregistrați-l o singură dată scanând codul. Dacă pierdeți telefonul, eliminați-l imediat de aici, pentru a nu mai putea aproba nimic.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Un spațiu de lucru este locul unei companii înregistrate în această instalare și conține proiectele, mediile și echipa sa. Deschideți-l pentru a consulta produsele și mediile sau suspendați-l: membrii vor fi deconectați, iar autentificarea va fi oprită în toate mediile sale.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Când o aplicație sau un agent AI are nevoie de acordul dvs. pentru a acționa în numele dvs., nu îl poate cere întotdeauna pe ecranul din fața dvs., așa că îl cere aici. Aprobați doar cererile inițiate de dvs. și verificați dacă acest cod corespunde celui de pe dispozitivul care a trimis cererea.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Un proiect reprezintă unul dintre produsele dvs., cu propriul plan, propria autentificare și medii precum producție și preproducție. Deschideți un mediu de aici pentru a-l administra. Creați un proiect nou când lansați un produs care trebuie facturat și operat separat.',
    'send_this_endpoint_every_organization_s_events_in_this_ea696387' => 'Trimiteți către acest endpoint evenimentele tuturor organizațiilor din acest mediu, nu doar ale uneia.',
    'signature_scheme_changed_deliveries_are_signed_the_new_9a0fb26a' => 'Schema de semnare a fost schimbată. Livrările vor fi semnate în noul mod începând cu următoarea încercare.',
    'the_hook_stops_being_called_and_its_signing_secret_is_d_ad833a77' => 'Hookul nu mai este apelat, iar secretul său de semnare este distrus. Acțiunea nu poate fi anulată.',
    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'Bucketul este în cale, nu în numele gazdei. Un endpoint personalizat folosește deja acest format.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Fiecare aplicație care autentifică persoane prin Cbox ID sau îi apelează API-ul este înregistrată aici și primește propriile credențiale. Înregistrați separat fiecare aplicație și fiecare mediu. Nu partajați credențialele, pentru a le putea revoca pentru una fără a le întrerupe pe celelalte.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Căutați o organizație după nume sau identificator ori un utilizator după nume sau e-mail în toate mediile acestei instalări, nu doar în cel selectat în consolă. Folosiți căutarea când cineva cere ajutor și nu știți în ce mediu se află.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Vedeți o aplicație exact ca unul dintre utilizatorii săi: vă autentificați în numele acestuia, cu un motiv declarat, pentru cel mult o oră. Aplicația este informată cine o accesează de fapt și nu primește posibilitatea de a menține sesiunea. Jurnalul de audit al organizației înregistrează cine a făcut acest lucru și de ce.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Un proiect este un produs IdP deținut de acest spațiu de lucru, de care aparțin mediile. Până când spațiul de lucru creează un proiect din propria consolă, nu există aici niciun mediu de selectat sau deschis. Acest ecran nu permite crearea unui proiect în numele spațiului de lucru.',
    'sign_in_with_face_id_touch_id_windows_hello__97a33786' => 'Autentificați-vă cu Face ID, Touch ID, Windows Hello sau o cheie de securitate, fără parolă.',
    'sign_ins_and_changes_to_your_password_passkeys_and_two_9e7da5c8' => 'Aici apar autentificările și modificările parolei, cheilor de acces și setărilor de autentificare cu doi factori.',
    'text_message_codes_are_no_longer_offered_her_1a9ddf89' => 'Codurile prin SMS nu mai sunt disponibile aici. Folosiți o aplicație de autentificare sau o cheie de acces.',
    'that_device_stops_being_able_to_sign_you_in__5e148d22' => 'Dispozitivul respectiv nu vă mai poate autentifica. Îl puteți adăuga din nou de pe această pagină.',
    'that_request_is_no_longer_waiting_it_was_answered_used_80728be7' => 'Cererea respectivă nu mai este în așteptare: a primit răspuns, a fost utilizată sau a expirat.',
    'the_agent_is_told_no_when_it_asks_again_and_has_to_star_c28d8870' => 'Când agentul întreabă din nou, primește un refuz și trebuie să reînceapă. Refuzul este înregistrat în jurnalul de audit.',
    'the_browser_tab_icon_on_your_sign_in_pages_a_square_png_04f6f405' => 'Pictograma filei de browser de pe paginile de autentificare. Imagine pătrată PNG, ICO sau WebP, de cel mult 256 KB.',
    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'Aspectul, sigla și faviconul paginii de autentificare găzduite, precum și numele și expeditorul afișate utilizatorilor.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Se trimite când este creat contul unei persoane. Lăsați gol pentru valoarea implicită.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Doar pentru un furnizor care nu publică cheile de semnare (jwks_uri) în documentul de descoperire. Altfel, cheile sunt citite de acolo, inclusiv după rotație. Introduceți o cheie publică PEM. Este stocată criptat și nu va mai fi afișată; lăsați necompletat pentru a păstra cheia actuală.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Anumite perechi de roluri nu trebuie să aparțină aceleiași persoane: cine inițiază o plată nu ar trebui să o și aprobe. Declarați perechile aici. Cbox ID blochează acordările noi care ar încălca regula și arată cine deține deja o pereche de roluri incompatibile.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Chei API și tokenuri necesare aplicațiilor și agenților pentru alte servicii, stocate criptat aici în locul configurației fiecărei aplicații. Introduceți secretul o singură dată și autorizați aplicații specifice să îl folosească. Nu va mai fi afișat; dacă îl pierdeți, înlocuiți-l.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Expune endpointurile de identitate ale unui mediu pe un domeniu propriu, precum login.example.com, în locul domeniului nostru. Dovediți că domeniul vă aparține printr-o înregistrare DNS TXT. Configurați-l când persoanele trebuie să vadă doar adresa dvs. în timpul autentificării.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Numele spațiului de lucru care reunește proiectele, mediile și echipa și care apare în întreaga consolă. Ștergerea unui spațiu de lucru oprește toate mediile folosite pentru autentificare. De aceea, se solicită echipei de asistență, nu printr-un buton.',
    'the_claim_is_dropped_if_capture_was_on_people_on_this_d_17d5c40e' => 'Revendicarea domeniului este eliminată. Dacă SSO obligatoriu era activat, persoanele din acest domeniu revin la autentificarea obișnuită.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Acest domeniu nu își va mai direcționa utilizatorii prin SSO-ul acestei organizații. Acțiunea nu poate fi anulată.',
