    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Fiecare organizație este o companie sau o echipă care folosește produsul dvs., cu propriii membri, propriile roluri, domenii și autentificare unică. Creați câte una pentru fiecare companie înregistrată. Deschideți-o pentru a gestiona membrii, invitațiile și domeniile verificate sau pentru a o suspenda.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID trimite un mesaj semnat către endpointul dvs. după un eveniment, precum adăugarea unui membru sau schimbarea unui rol, astfel încât sistemele să reacționeze fără interogări periodice. Livrarea eșuată este reîncercată. Evenimentul s-a produs deja: endpointul este informat, dar nu decide rezultatul.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'O schemă definește structura evenimentelor unei acțiuni: tipurile de ținte indicate și conținutul metadatelor. Evenimentele unei acțiuni cu schemă sunt verificate la primire. Fără schemă, sunt acceptate așa cum sunt trimise, exceptând cazul în care modul strict este activ.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Toate persoanele care administrează acest spațiu de lucru, rolul predefinit al fiecăreia — Proprietar, Administrator, Dezvoltator, Membru sau Observator — și mediile accesibile. Invitați persoane prin e-mail și acordați fiecăreia doar mediile necesare activității sale.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Permiteți utilizatorilor aplicațiilor să își conecteze propriile conturi GitHub, Google, Slack sau Salesforce, astfel încât aplicațiile să apeleze acele API-uri în numele lor. Tokenurile sunt stocate criptat și reîmprospătate aici, iar accesul temporar este acordat doar aplicațiilor autorizate.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Persoana invitată acceptă prin e-mail. Nimeni nu este adăugat într-o organizație fără să își dea acordul.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Acest utilizator nu are sesiuni autentificate acum. Acestea apar aici după ce se autentifică.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Acest utilizator trebuie să își schimbe parola. Nu poate accesa nimic până când nu o înlocuiește pe cea pe care i-ați furnizat-o.',
    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Utilizator creat. Nu se poate autentifica până când nu îi trimiteți un link.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Datele utilizatorului au fost șterse. Contul a fost pseudonimizat, iar ștergerea este înregistrată ca user.erased în jurnalul de audit.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Operatorii platformei administrează toate spațiile de lucru și mediile acestei instalări, deasupra nivelului fiecăruia. Adăugați un operator doar pentru cineva care gestionează instalarea propriu-zisă și suspendați-l când această responsabilitate încetează.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Toate organizațiile din mediul selectat în consolă, într-un arbore de revânzători, organizații administrate de aceștia și subunități. Aici puteți crea sau suspenda o organizație ori o puteți muta sub altă organizație părinte.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Autentificări, tokenuri emise, utilizatori noi și înregistrări pentru autentificarea cu doi factori, pe zile, în ultimele 30 de zile, dacă instalarea nu stabilește alt interval. Pagina rămâne goală până când administratorul instalării configurează stocarea datelor analitice.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Setați această politică de încredere pentru rol (IAM › Roles › Trust relationships). Platforma poate asuma rolul doar când prezintă ID-ul extern al acestui flux, astfel încât nimeni altcineva de pe platformă să nu poată direcționa un flux către rolul dvs.',
    'their_it_contact_left_blank_you_copy_the_lin_2fe54822' => 'Persoana de contact IT. Dacă lăsați câmpul gol, copiați singur linkul.',
    'presets_colours_corners_type_edited_with_a_live_preview_ff61e898' => 'Presetări, culori, colțuri și tipografie, editate cu previzualizare în timp real.',
    'where_a_copy_of_every_audit_entry_is_delivered_as_it_is_c6b9e401' => 'Destinația unde se livrează o copie a fiecărei înregistrări de audit imediat ce este scrisă.',
    'where_sign_ins_go_for_people_who_have_not_moved_to_cbox_be5f68b3' => 'Destinația autentificărilor persoanelor care nu au migrat încă la Cbox ID.',
    'where_the_provider_posts_its_assertion_give_this_to_who_5b098f34' => 'Adresa la care furnizorul trimite aserțiunea. Comunicați-o persoanei care configurează IdP-ul.',
    'where_the_signed_assertion_is_posted_back_must_be_https_2dc6e396' => 'Adresa la care este trimisă înapoi aserțiunea semnată. Trebuie să folosească https.',
    'where_we_exchange_the_client_credentials_for_a_short_li_2afa7c75' => 'Destinația unde schimbăm datele de autentificare ale clientului pentru un token de scurtă durată înainte de fiecare lot.',
    'who_connected_an_account_through_this_pipe_tokens_are_n_ea456475' => 'Cine a conectat un cont prin această conexiune. Tokenurile nu sunt niciodată afișate.',
    'this_connection_belongs_to_the_environment_itself_it_si_543963d3' => 'Această conexiune aparține mediului însuși. Autentifică persoanele fără să le adauge în vreo organizație.',
    'this_organization_s_entries_and_nothing_from_any_other_1ab06e62' => 'Înregistrările acestei organizații, fără nimic din alte organizații.',
    'what_you_create_here_belongs_to_this_organization_and_t_fc8e15c4' => 'Ceea ce creați aici aparține exclusiv acestei organizații.',
    'whose_people_are_pushed_or_tick_the_box_above_to_send_e_bb15010f' => 'Persoanele cărei organizații sunt trimise — sau bifați opțiunea de mai sus pentru a trimite toate organizațiile.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Persoanele cărei organizații se autentifică prin această conexiune. Domeniile și linkul către portalul de administrare se află pe pagina organizației.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Toate browserele și dispozitivele conectate la contul dvs., aplicațiile autorizate să acționeze în numele dvs. și autentificările și modificările de securitate recente. Dacă nu recunoașteți o activitate, închideți sesiunea sau revocați accesul aplicației, apoi schimbați parola.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Toate modificările din această organizație: cine a făcut ce, asupra cărui obiect și când. Intrările sunt legate prin hashuri, astfel încât ștergerea sau modificarea unei intrări rupe lanțul și poate fi detectată. Este intenționat doar pentru citire: acesta este registrul oferit unui auditor.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Lăsați necompletat pentru aproape toți furnizorii: tokenurile ID sunt verificate cu cheile de semnare publicate în documentul de descoperire (jwks_uri), inclusiv după rotație. Lipiți cheia publică PEM a furnizorului doar dacă nu publică nicio cheie.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Autentificările și cererile pe care Cbox ID le-a evaluat ca suficient de riscante pentru a fi semnalate, cele mai recente primele, cu scorul și motivele. Verificați aici după o creștere a autentificărilor eșuate sau când cineva raportează o autentificare pe care nu a inițiat-o.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Acest mediu oferă un server MCP alături de API-ul REST. Conectați un agent cu o cheie de administrare, iar acesta poate face exact ce permit domeniile cheii, cu aceleași verificări, aprobări și jurnal de audit ca în consolă.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Nicio înregistrare nu corespunde acestor filtre. Extindeți intervalul sau eliminați un filtru.',
    'searches_organizations_and_users_across_every_environme_031a8626' => 'Căutați organizații și utilizatori în toate mediile acestei instalări.',
    'the_ten_organizations_with_the_most_members_and_the_env_1c7ea5a5' => 'Cele zece organizații cu cei mai mulți membri și mediul căruia îi aparține fiecare',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Cine este autentificat acum ca această persoană. Radar arată de ce o autentificare a fost permisă, supusă unei verificări suplimentare sau blocată.',
    'what_this_organization_s_sign_in_is_wired_to_read_from_cde71601' => 'La ce este conectată autentificarea acestei organizații, conform configurației reale.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Furnizorul propriu al unei organizații îl înlocuiește pe cel al mediului pe pagina sa de autentificare. Sunt listate și organizațiile care au dezactivat furnizorul mediului. Aceasta elimină doar butonul de pe pagină; impunerea SSO este cea care împiedică accesul prin această metodă.',
